// Browser port of training.protocol.clean_text. Parity with Python is checked in
// tests/clean.test.js against fixtures generated by scripts/clean_fixtures.py.
import table from './casefold.json';

const FOLD = table.fold;
// Exactly the characters Python's str.isspace() accepts (and so `\s` in a str pattern).
const WS = '\\t\\n\\v\\f\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000';
const URL_RE = new RegExp(`https?:\\/\\/[^${WS}]+|www\\.[^${WS}]+`, 'gu');
const MENTION_RE = /@[\p{L}\p{N}_]+/gu;
const WS_RUN = new RegExp(`[${WS}]+`, 'gu');
const EDGE = new RegExp(`^[${WS}]+|[${WS}]+$`, 'gu');

export function casefold(text) {
  let out = '';
  for (const ch of text) out += FOLD[ch] ?? ch;
  return out;
}

export function cleanText(value) {
  if (typeof value !== 'string') return '';
  let text = casefold(value.normalize('NFKC'));
  text = text.replace(URL_RE, ' ');
  text = text.replace(MENTION_RE, ' ');
  return text.replaceAll('#', '').replace(WS_RUN, ' ').replace(EDGE, '');
}
